WORDS = {"설비": "EQP", "번호": "NO", "가동": "OPR", "시작": "STRT", "일시": "DTM", "공장": "PLNT", "코드": "CD"}
DOMAINS = {"번호": "VARCHAR(20)", "일시": "TIMESTAMP", "코드": "CHAR(4)"}

def term(korean):
    parts = korean.split()
    return "_".join(WORDS[p] for p in parts), DOMAINS.get(parts[-1], "?")

for t in ["설비 번호", "설비 가동 시작 일시", "공장 코드"]:
    print(t, "->", *term(t))

plant_cols = {"A공장 MES": ["EQP_NO", "EQUIP_ID", "OPR_STRT_DTM"], "B공장 MES": ["EQP_NO", "START_TIME", "PLANT"]}
std = {term(t)[0] for t in ["설비 번호", "설비 가동 시작 일시", "공장 코드"]}
for sys_, cols in plant_cols.items():
    print(sys_, "비표준:", [c for c in cols if c not in std])
# 설비 번호 -> EQP_NO VARCHAR(20)
# 설비 가동 시작 일시 -> EQP_OPR_STRT_DTM TIMESTAMP
# 공장 코드 -> PLNT_CD CHAR(4)
# A공장 MES 비표준: ['EQUIP_ID', 'OPR_STRT_DTM']
# B공장 MES 비표준: ['START_TIME', 'PLANT']
